import { boot } from 'quasar/wrappers';
import { logger } from 'src/utils/logger';
import { safeBoot } from 'src/utils/bootSafety';

declare global {
  function logError(message: unknown, context?: any): void;
  function logInfo(message: unknown, context?: any): void;
  function logDebug(message: unknown, context?: any): void;
  function logWarn(message: unknown, context?: any): void;
}

// HMR guard to prevent multiple initializations during hot reload
let isInitialized = false;

export function stringifyLogMessage(value: unknown): string {
  if (value instanceof Error) {
    return value.message || value.name;
  }

  if (typeof value === 'string') {
    return value;
  }

  if (value === null) {
    return 'null';
  }

  if (value === undefined) {
    return 'undefined';
  }

  if (typeof value === 'object') {
    const message = (value as { message?: unknown }).message;
    if (typeof message === 'string' && message.trim()) {
      return message;
    }

    try {
      return JSON.stringify(value);
    } catch {
      return Object.prototype.toString.call(value);
    }
  }

  return String(value);
}

export function normalizeGlobalLogArgs(message: unknown, context?: any): any[] {
  const normalizedMessage = stringifyLogMessage(message);

  if (context === undefined) {
    return message instanceof Error ? [normalizedMessage, message] : [normalizedMessage];
  }

  if (typeof context === 'string' && typeof message !== 'string') {
    return [context, message];
  }

  return [normalizedMessage, context];
}

/**
 * Logger Boot File
 *
 * Sets up global logging functions for use throughout the application.
 * Console output only — telemetry is handled by Faro (src/boot/faro.ts).
 */
export default boot(safeBoot('logger', () => {
  if (isInitialized && import.meta.hot) {
    return;
  }

  globalThis.logError = (message: unknown, context?: any) => {
    logger.error(...normalizeGlobalLogArgs(message, context));
  };

  globalThis.logInfo = (message: unknown, context?: any) => {
    logger.debug(...normalizeGlobalLogArgs(message, context));
  };

  globalThis.logDebug = (message: unknown, context?: any) => {
    logger.debug(...normalizeGlobalLogArgs(message, context));
  };

  globalThis.logWarn = (message: unknown, context?: any) => {
    logger.warn(...normalizeGlobalLogArgs(message, context));
  };

  isInitialized = true;
}));

// HMR cleanup
if (import.meta.hot) {
  import.meta.hot.dispose(() => {
    isInitialized = false;
  });
}
